head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = 'ULDBNS22100.xml';
scwin.todat = "";
scwin.grd_HandOverIsuList_nm = "";
scwin.grd_TakeOverIsuList_nm = "";
scwin.grd_byCorpList_nm = "";
scwin.grd_chgByCorpList_nm = "";
scwin.grd_allByCorpList_nm = "";
scwin.gubun = 0; //어느화면에서 수정했는지 체크.

scwin.tmpIdx1 = "";
scwin.tmpIdx2 = "";
scwin.gBizTpCd = "";
scwin.gLdMktTpCd = "";
scwin.gUpDepCd = "";
scwin.gETFYn = "N";
scwin.all_list_count = 0; // 전체 담당지정 법인 목록	
scwin.filter_cnt = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //filter된 법인목록


//조회
scwin.fn_list_usr_sync = function() {
    vIsurNm = $c.stf.getObjectValue(txb_IsurCd);
    var dsNm = 'BNS_ISUR_INFO';
    var qryId = 'lds.stf.bnslistbzappl.select.listIsurCd.bnsApplPosblTmExcptYn';
    var param = '&{P}V_ISUR_NM=' + vIsurNm;
    param += '&{P}V_EXCPT_YN=N';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_HandOverIsuList, dsNm, qryId, param);
    $c.cm.ShowWin(grd_HandOverIsuList);
    var dsNm = 'BNS_ISUR_INFO';
    var qryId = 'lds.stf.bnslistbzappl.select.listIsurCd.bnsApplPosblTmExcptYn';
    var param = '&{P}V_ISUR_NM=';
    param += '&{P}V_EXCPT_YN=Y';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_TakeOverIsuList, dsNm, qryId, param);
    $c.cm.ShowWin(grd_TakeOverIsuList);
};



/*----------------------------------------------------------------------------
	** 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. 
-------------------------------------------------------------------------------*/
scwin.fn_cntDatasetRowCheck = function(sval) {
    cCnt = 0;
    for (i = 1; i <= sval.getTotalRow(); i++) {
        //alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") == 1) {
            cCnt++;
        }
    }
    if (cCnt == 0) {
        return false;
    } else {
        return true;
    }
};



/*----------------------------------------------------------------------------
	** 예외처리
-------------------------------------------------------------------------------*/
scwin.fn_All_HandOver = function() {
    //gubun = 1;
    var rowcnt = dts_HandOverIsuList.getTotalRow();
    if (rowcnt == 0) {
        $c.win.alert("처리할 사항이 없습니다.");
        return;
    }
    if (!scwin.fn_cntDatasetRowCheck(dts_HandOverIsuList)) {
        $c.win.alert("적용할 체크사항이 없습니다.");
    } else {
        var msg = $c.stf.getMessageParam("MSG-A006", "예외처리");
        var res = window.confirm(msg);
        if (res) {

            //dts_Save.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
            for (var i = 1; i <= dts_HandOverIsuList.getTotalRow(); i++) {
                if (dts_HandOverIsuList.getCellData(i, "CHK_FLAG") == 1) {
                    dts_Save.insertRow();
                    dts_Save.setCellData(dts_Save.getRowPosition(), "ISUR_CD", dts_HandOverIsuList.getCellData(i, "ISUR_CD"));
                }
            }
            trs_Save.Action = "/bns/IsuChgEtc.do?method=updateBndApplTmExcptSaveBtn&V_EXCPT_YN=Y&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
            trs_Save.Post();
        }
    }
};





/*----------------------------------------------------------------------------
	** 신청제한처리
-------------------------------------------------------------------------------*/
scwin.fn_Select_TakeOver = function() {
    //gubun = 1;
    var rowcnt = dts_TakeOverIsuList.getTotalRow();
    if (rowcnt == 0) {
        $c.win.alert("처리할 사항이 없습니다.");
        return;
    }
    if (!scwin.fn_cntDatasetRowCheck(dts_TakeOverIsuList)) {
        $c.win.alert("적용할 체크사항이 없습니다.");
    } else {
        var msg = $c.stf.getMessageParam("MSG-A006", "신청제한");
        var res = window.confirm(msg);
        if (res) {

            //dts_Save.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
            for (var i = 1; i <= dts_TakeOverIsuList.getTotalRow(); i++) {
                if (dts_TakeOverIsuList.getCellData(i, "CHK_FLAG") == 1) {
                    dts_Save.insertRow();
                    dts_Save.setCellData(dts_Save.getRowPosition(), "ISUR_CD", dts_TakeOverIsuList.getCellData(i, "ISUR_CD"));
                }
            }
            trs_Save.Action = "/bns/IsuChgEtc.do?method=updateBndApplTmExcptSaveBtn&V_EXCPT_YN=N&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
            trs_Save.Post();
        }
    }
};
scwin.dts_HandOverIsuList_OnLoadCompleted = function(rowcount) {
    cnt1.setValue(rowcount + " 건");
    $c.cm.CloseWin(rowcount, grd_HandOverIsuList);
};
scwin.dts_TakeOverIsuList_OnLoadCompleted = function(rowcount) {
    cnt2.setValue(rowcount + " 건");
    $c.cm.CloseWin(rowcount, grd_TakeOverIsuList);
};
scwin.dts_HandOverIsuList_OnLoadError = function() {
    $c.stf.alert_error(dts_HandOverIsuList);
};
scwin.dts_TakeOverIsuList_OnLoadError = function() {
    $c.stf.alert_error(dts_TakeOverIsuList);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    scwin.fn_list_usr_sync();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    scwin.fn_list_usr_sync();
};
scwin.gform_onload = function() {
    scwin.fn_list_usr_sync();
    $c.bns.BnsPanelToGroupBox(panel_2);
    $c.bns.BnsPanelToGroupBox(pnl_IsurSearch);
};
scwin.grd_HandOverIsuList_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.grd_TakeOverIsuList_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.btn_Select_HandOver_onclick = function() {
    scwin.fn_Select_TakeOver();
};
scwin.btn_All_HandOver_onclick = function() {
    scwin.fn_All_HandOver();
};
scwin.txb_IsurCd_onkeypress = function() {
    if (event.keyCode == 13) scwin.fn_list_usr_sync();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_usr_sync();
};
